def _config_path_from_args(args: Sequence[str]) -> str:
    """åœ¨ Click è§£æžå‚æ•°å‰å–å¾—å…¨å±€é…ç½®è·¯å¾„ï¼Œç¡®ä¿å¸®åŠ©ç­‰æ—©é€€å‘½ä»¤ä¹Ÿä¼šåˆå§‹åŒ–ã€‚"""
    for index, arg in enumerate(args):
        if arg in {"--config", "-c"}:
            if index + 1 < len(args):
                return args[index + 1]
            break
        if arg.startswith("--config="):
            return arg.partition("=")[2]
        if arg.startswith("-c") and len(arg) > 2:
            return arg[2:]
    return "config.yaml"


class _ConfigInitializingGroup(TyperGroup):
    """æ‰€æœ‰ CLI è°ƒç”¨åœ¨ Click åˆ†æ´¾æˆ–æ—©é€€å‰éƒ½æ£€æŸ¥é»˜è®¤é…ç½®ã€‚"""

    def main(
        self,
        args: Sequence[str] | None = None,
        *main_args: Any,
        **main_kwargs: Any,
    ) -> Any:
        """åœ¨ Click è§£æžå‘½ä»¤å‰å®šä½å¹¶åˆ›å»ºç¼ºå¤±çš„é»˜è®¤é…ç½®æ–‡ä»¶ã€‚"""
        cli_args = list(args) if args is not None else sys.argv[1:]
        config_path = _config_path_from_args(cli_args)
        _CONFIG["path"] = config_path
        _CONFIG["skip_api_check"] = any(arg in {"--help", "-h"} for arg in cli_args)
        Config.create_default_file(config_path)
        return super().main(*main_args, args=args, **main_kwargs)


