@app.callback()
def _root(
    ctx: typer.Context,
    config: str = typer.Option(
        "config.yaml",
        "--config",
        "-c",
        help="é…ç½®æ–‡ä»¶è·¯å¾„ï¼›æ–‡ä»¶ä¸å­˜åœ¨æ—¶è‡ªåŠ¨åˆ›å»º",
    ),
    version: bool = typer.Option(
        False,
        "--version",
        callback=_version_callback,
        is_eager=True,
        help="æ˜¾ç¤ºç‰ˆæœ¬å·å¹¶é€€å‡º",
    ),
):
    """è®°å½•å…¨å±€é…ç½®è·¯å¾„ï¼Œå¹¶åœ¨å­å‘½ä»¤è¿è¡Œå‰æ ¡éªŒæ¨¡åž‹å‡­æ®ã€‚"""
    del version
    _CONFIG["path"] = config
    command = ctx.invoked_subcommand
    should_validate = (
        not _CONFIG.get("skip_api_check")
        and command is not None
        and command not in _API_CHECK_EXEMPT_COMMANDS
    )
    if should_validate:
        try:
            _validate_api_configuration()
        except (OSError, RuntimeError, ValueError) as error:
            console.print(f"[red]é”™è¯¯ï¼š{error}[/]")
            raise typer.Exit(1) from None


