def _validate_api_configuration() -> None:
    """æž„å»ºå½“å‰ provider å¹¶åœ¨ä»»ä½•å‘½ä»¤é€»è¾‘å‰æ ¡éªŒæ‰€éœ€ API å‡­æ®ã€‚"""
